contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public entry: attempt a withdraw of `amount` from C
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);

        // record observable pre-state
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint balanceC_before = address(c).balance;
        uint balanceSelf_before = address(this).balance;

        // perform exactly one state-changing call on c as a top-level statement
        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // record observable post-state
        uint balanceC_after = address(c).balance;
        uint balanceSelf_after = address(this).balance;

        // General rule:
        // - If this contract is the owner and C had at least `amount` before the call: the call must NOT revert
        //   and balances change exactly by `amount` (C decreases by amount, this increases by amount).
        // - Otherwise (not owner OR C balance < amount): the call must revert and balances stay the same.
        assert(
            (ownerBefore == address(this) && balanceC_before >= amount && reverted == false && balanceC_before - balanceC_after == amount && balanceSelf_after - balanceSelf_before == amount)
            ||
            ((ownerBefore != address(this) || balanceC_before < amount) && reverted == true && balanceC_after == balanceC_before && balanceSelf_after == balanceSelf_before)
        );
    }

    receive() external payable { }
}

