// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(true);
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        uint balanceC_before = address(c).balance;
        uint balanceSelf_before = address(this).balance;
        bool reverted;
        try c.withdraw(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint balanceC_after = address(c).balance;
        uint balanceSelf_after = address(this).balance;
        assertTrue((ownerBefore == address(this) && balanceC_before >= amount && reverted == false && balanceC_before - balanceC_after == amount && balanceSelf_after - balanceSelf_before == amount)
            ||
            ((ownerBefore != address(this) || balanceC_before < amount) && reverted == true && balanceC_after == balanceC_before && balanceSelf_after == balanceSelf_before));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable { }
}
